import { useState, useEffect } from 'react';
import './App.css';

function App() {
  const [isVisible, setIsVisible] = useState(false);
  const [selectedTab, setSelectedTab] = useState(0);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  const scrollToInfo = () => {
    window.scrollTo({
      top: window.innerHeight,
      behavior: 'smooth'
    });
  };

  const joinDiscord = () => {
    window.open('https://discord.gg/ASSnBjyt', '_blank');
  };

  return (
    <div className="gaming-site">
      {/* Floating Discord Button */}
      <div className="floating-discord-btn">
        <button 
          className="discord-float-button"
          onClick={joinDiscord}
          title="Join Discord Server"
        >
          <span className="discord-icon">💬</span>
          <span className="discord-text">Join discord and start playing</span>
        </button>
      </div>

      {/* Hero Section - Full Screen */}
      <section className="hero-section">
        {/* ...existing code... */}
      </section>

      {/* Quick Overview Section */}
      <section className="quick-overview-section">
        {/* ...existing code... */}
      </section>

      {/* Server Information Section - Redesigned as Side Tab Layout */}
      <section className="server-info-section" style={{display: 'flex', minHeight: '70vh', background: '#181c2f', borderRadius: '20px', margin: '40px 0', boxShadow: '0 4px 24px rgba(0,0,0,0.15)'}}>
        <div className="side-header" style={{
          minWidth: 240,
          background: 'linear-gradient(135deg, #1e223a 0%, #23284a 100%)',
          borderTopLeftRadius: 20,
          borderBottomLeftRadius: 20,
          borderRight: 'none',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'flex-start',
          padding: '40px 0 40px 0',
          boxShadow: '2px 0 8px 0 rgba(0,0,0,0.04)',
          border: 'none',
        }}>
          {['How To Join Games', 'What Is Vanilla Civ Mod(kekmod)', '30 sec install and uninstallation guide for Mod', 'Server introduction', 'Server Rules'].map((tab, idx) => (
            <button
              key={tab}
              className={`side-tab-btn${selectedTab === idx ? ' active' : ''}`}
              style={{
                background: selectedTab === idx ? 'rgba(0,212,255,0.12)' : 'transparent',
                color: selectedTab === idx ? '#00d4ff' : '#e0e0e0',
                border: 'none',
                outline: 'none',
                fontWeight: 600,
                fontSize: 18,
                padding: '18px 32px',
                width: '100%',
                textAlign: 'left',
                borderRadius: 0,
                borderLeft: selectedTab === idx ? '4px solid #00d4ff' : '4px solid transparent',
                transition: 'background 0.2s, color 0.2s',
                cursor: 'pointer',
              }}
              onClick={() => setSelectedTab(idx)}
            >
              {tab}
            </button>
          ))}
        </div>
        <div className="tab-content" style={{
          flex: 1,
          background: 'linear-gradient(135deg, #23284a 0%, #181c2f 100%)',
          borderTopRightRadius: 20,
          borderBottomRightRadius: 20,
          padding: '40px 48px',
          color: '#e0e0e0',
          minHeight: 400,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'flex-start',
        }}>
          {selectedTab === 0 && (
            <>
              <h2>How To Join Games</h2>
              <p>Join our Discord and go to <strong>#LFG</strong> to find games, or <strong>#Draft</strong> to create lobbies. All games use the vanilla Civ 5 mod (kekmod). Ask in Discord for help if needed!</p>
            </>
          )}
          {selectedTab === 1 && (
            <>
              <h2>What Is Vanilla Civ Mod (kekmod)?</h2>
              <p>The vanilla Civ 5 mod (kekmod) is a lightweight mod that enables competitive play with fair rules and bugfixes. It is required for all games on this server.</p>
            </>
          )}
          {selectedTab === 2 && (
            <>
              <h2>30 sec Install & Uninstall Guide for Mod</h2>
              <ol>
                <li>Download the mod from our Discord #mod-downloads channel.</li>
                <li>Extract the .civ5mod file to your Civ 5 MODS folder.</li>
                <li>Enable the mod in-game before joining a lobby.</li>
                <li>To uninstall, simply delete the mod file from the MODS folder.</li>
              </ol>
            </>
          )}
          {selectedTab === 3 && (
            <>
              <h2>Server Introduction</h2>
              <p>Welcome to the most advanced Civ 5 Discord community! We offer competitive, no-quit games, democratic governance, and a fair ELO system. Join us and become part of a unique multiplayer experience.</p>
            </>
          )}
          {selectedTab === 4 && (
            <>
              <h2>Server Rules</h2>
              <ul>
                <li>No quitting without a vote</li>
                <li>All games use kekmod</li>
                <li>Respect other players</li>
                <li>Follow Discord and in-game rules</li>
                <li>See Discord for full rules list</li>
              </ul>
            </>
          )}
        </div>
      </section>

      {/* Simple Game Info Section */}
      <section className="game-info-section" style={{background: 'linear-gradient(135deg, #16213e 0%, #0f0f23 100%)', padding: '80px 20px', textAlign: 'center'}}>
        {/* ...existing code... */}
      </section>

      {/* Final Overall CTA */}
      {/* ...existing code... */}
    </div>
  );
}

export default App;
